"""SOLUTION:"""
import itertools
import json

# Helper functions for time handling
def to_minutes(h, m):
    return h * 60 + m

def minutes_to_str(t):
    h = t // 60
    m = t % 60
    return f"{h}:{m:02d}"

# Input variables (constraints and travel times)

start_location = "Sunset District"
start_time = to_minutes(9, 0)

# Travel times in minutes between locations
travel = {
    "Sunset District": {
        "Alamo Square": 17,
        "Russian Hill": 24,
        "Presidio": 16,
        "Financial District": 30,
    },
    "Alamo Square": {
        "Sunset District": 16,
        "Russian Hill": 13,
        "Presidio": 18,
        "Financial District": 17,
    },
    "Russian Hill": {
        "Sunset District": 23,
        "Alamo Square": 15,
        "Presidio": 14,
        "Financial District": 11,
    },
    "Presidio": {
        "Sunset District": 15,
        "Alamo Square": 18,
        "Russian Hill": 14,
        "Financial District": 23,
    },
    "Financial District": {
        "Sunset District": 31,
        "Alamo Square": 17,
        "Russian Hill": 10,
        "Presidio": 22,
    },
}

# Friends' availability and requirements
friends = {
    "Kevin": {
        "location": "Alamo Square",
        "start": to_minutes(8, 15),
        "end": to_minutes(21, 30),
        "min_dur": 75,
    },
    "Kimberly": {
        "location": "Russian Hill",
        "start": to_minutes(8, 45),
        "end": to_minutes(12, 30),
        "min_dur": 30,
    },
    "Joseph": {
        "location": "Presidio",
        "start": to_minutes(18, 30),
        "end": to_minutes(19, 15),
        "min_dur": 45,
    },
    "Thomas": {
        "location": "Financial District",
        "start": to_minutes(19, 0),
        "end": to_minutes(21, 45),
        "min_dur": 45,
    },
}

# Evaluate a given ordered sequence of friends to meet
def evaluate_sequence(order):
    current_loc = start_location
    current_time = start_time
    itinerary = []
    total_travel = 0

    for name in order:
        info = friends[name]
        loc = info["location"]
        # Get travel time; if missing, not feasible
        if current_loc not in travel or loc not in travel[current_loc]:
            return None
        move = travel[current_loc][loc]
        total_travel += move
        arrival = current_time + move

        # Wait until availability if early
        start_meet = max(arrival, info["start"])
        end_meet = start_meet + info["min_dur"]

        # Must finish by the friend's end time
        if end_meet > info["end"]:
            return None

        itinerary.append({
            "action": "meet",
            "location": loc,
            "person": name,
            "start_time": minutes_to_str(start_meet),
            "end_time": minutes_to_str(end_meet),
        })

        current_loc = loc
        current_time = end_meet

    return {
        "itinerary": itinerary,
        "count": len(itinerary),
        "finish_time": current_time,
        "total_travel": total_travel,
    }

# Generate and choose the optimal schedule
all_names = list(friends.keys())

best = None

# Primary objective: maximize number met
# Tie-break 1: minimize total travel time
# Tie-break 2: minimize finish time
for k in range(len(all_names), 0, -1):
    for combo in itertools.combinations(all_names, k):
        # Explore all meeting orders
        for perm in itertools.permutations(combo):
            result = evaluate_sequence(perm)
            if result is None:
                continue
            if best is None:
                best = result
            else:
                # Compare according to objectives
                if result["count"] > best["count"]:
                    best = result
                elif result["count"] == best["count"]:
                    if result["total_travel"] < best["total_travel"]:
                        best = result
                    elif result["total_travel"] == best["total_travel"]:
                        if result["finish_time"] < best["finish_time"]:
                            best = result
    if best is not None and best["count"] == k:
        # Found at least one schedule meeting k friends; since we loop k descending,
        # this is maximal and we can stop.
        break

# Output JSON with the optimal itinerary
output = {"itinerary": best["itinerary"] if best else []}
print(json.dumps(output))
